"""Authored first release: Python for ML, MLOps, and a guided regression project."""
VERSION='focused-ml-path-v1'
FOCUS_MODULES=['python','mlops','projects']
TOPICS=[
 ('python-for-ml','Python for ML: prepare reliable data','python'),
 ('mlops-basics','MLOps: track, save and serve models','mlops'),
 ('ml-project','Delivery-time prediction project','projects'),
]

