def install(modules,submodules,lessons,questions,catalog):
    module_index={m['id']:m for m in modules}
    if 'projects' not in module_index:
        project_module={'id':'projects','title':'Guided ML project','reason':'Connect preparation, evaluation and deployment in one runnable delivery-time project.','prerequisites':['python','mlops'],'submodules':[]}
        modules.append(project_module);module_index['projects']=project_module
    module_index['python']['title']='Python for ML'
    for sid,title,owner in TOPICS:
        topic={'id':sid,'title':title,'module_id':owner,'available':True,
            'difficulty':['beginner','foundational','intermediate','advanced'],'estimated_hours':None,
            'prerequisite_topic_ids':[] if sid=='python-for-ml' else ['python-for-ml'],
            'learning_objectives':[p['objective'] for p in PACKS if p['topic']==sid], 'release_focus':True}
        submodules[sid]=topic;catalog['topics'].append(topic)
        module_index[owner]['submodules'].insert(0,(sid,title,True))
        catalog['role_topics'].append({'role_id':'ai-engineer','topic_id':sid,'importance':'core',
            'recommended_order':FOCUS_MODULES.index(owner)+1,'source_titles':[title],'section_ids':[],
            'context':'Focused ML first release','source_kind':'focused_ml_release'})
    for p in PACKS:
        sid=p['topic'];lesson_id=sid+'-'+p['level'];owner=submodules[sid]['module_id']
        sections=[{'heading':h,'text':t} for h,t in [('Learning objective',p['objective']),('Before you begin',p['prerequisites']),
            ('What it is and why it matters',p['why']),('Understand the concept',p['concept']),('Worked example',p['example']),
            ('Guided exercise',p['guided']),('Independent challenge',p['challenge'])]]
        lessons.append({'id':lesson_id,'version':1,'title':p['title'],'skill':p['skill'],'minutes':25,
            'module_id':owner,'submodule_id':sid,'level':p['level'],'sections':sections,'takeaway':p['objective'],
            'runnable_code':p['code'],'expected_output':p['output'],'status':'complete','release':VERSION,
            'code_instructions':'Run locally with Python 3. For NumPy, pandas, scikit-learn or FastAPI imports, install examples/ml_project/requirements.txt first. The app does not execute submitted code.',
            'mini_project':{'title':'Apply this to the delivery-time project','task':p['project'],
                'rubric':[{'criterion':k,'description':v} for k,v in p['rubric'].items()], 'question_id':lesson_id+'-project'},
            'further_reading':READING[sid],'next_topic_ids':p['next'],
            'prerequisite_topic_ids':submodules[sid]['prerequisite_topic_ids']})
        for suffix,prompt,rubric,reference,activity in [
            ('check',p['quiz'],p['quiz_rubric'],p['quiz_reference'],'concept_check'),
            ('transfer',p['transfer'],p['quiz_rubric'],p['quiz_reference'],'concept_check'),
            ('project',p['project'],p['rubric'],p['reference'],'mini_project'),
            ('challenge',p['challenge'],p['challenge_rubric'],p['challenge_reference'],'mini_project')]:
            questions.append({'id':lesson_id+'-'+suffix,'version':1,'skill':p['skill'],'lesson_id':lesson_id,
                'module_id':owner,'submodule_id':sid,'topic_id':sid,'level':p['level'],'prompt':prompt,
                'hint':p['objective'],'criteria':list(rubric),'criterion_descriptions':rubric,
                'reference':reference,'activity':activity,'release':VERSION})
